var r=`0342-bratwurst`;var t=`world-0342`;var s=`DE`;var n=`western-europe`;var a=4;var u=30;var g={en:`Bratwurst`,ua:`Братвурст`};var o={en:`Seasoned ground-pork bratwurst-style patties; for authentic bratwurst sausages use catalog bratwurst, as casings are not included.`,ua:`Котлетки зі свинячого фаршу з приправами в стилі братвурст; для автентичних ковбасок потрібні оболонки, яких немає в каталозі.`};var l=[{en:`Combine ground pork with spices, chill and shape into small bratwurst-like rolls; this is a casing-free version.`,ua:`Змішайте свинячий фарш зі спеціями, охолодіть і сформуйте невеликі ковбаски без оболонки, адаптований варіант братвурсту.`,t:[`mixing`],m:12,i:[[`ground-pork`,700,`g`],[`table-salt`,10,`g`],[`ground-white-pepper`,4,`g`],[`ground-nutmeg`,3,`g`],[`dried-marjoram`,4,`g`]]},{en:`Grill over medium-high heat for about 16 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 16 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:16,i:[[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`dijon-mustard`,75,`g`],[`sauerkraut`,230,`g`]]}];var d={slug:r,id:t,country:`DE`,region:n,servings:4,minutes:30,title:g,text:o,steps:l};export{s as country,d as default,t as id,u as minutes,n as region,a as servings,r as slug,l as steps,o as text,g as title};